    const tree = this.parse(this.sampleXml());
    const expanded = new Set();
    if(tree){
      expanded.add(tree.id);
      (tree.children||[]).forEach(c=>expanded.add(c.id));
      const dp=(tree.children||[]).find(c=>c.tag==='DeviceProfiles');
      if(dp) (dp.children||[]).forEach(d=>expanded.add(d.id));
    }
