  ruTag(t){ return ({Metabase:'Метабаза',Props:'Свойства БД',Units:'Единицы измерения',Enums:'Перечисления',DeviceProfiles:'Профили устройств',Dev:'Устройство',FWVersions:'Версии прошивки',Softwares:'Программное обеспечение',CondGroups:'Условные группы',MsgLists:'Списки сообщений',Settings:'Настройки',Values:'Значения',Items:'Элементы списка',Name:'Имя',Description:'Описание',EditorConfig:'Конфигурация редактора',ComboEdit:'Выпадающий список',Filename:'Имя файла',Comments:'Комментарии'})[t]||t; }
